"""Shared document/data helpers; no retired Zhongshu execution."""
from ..errors import SOLVER_STRUCTURE_REPLY_PREFIX
_GATE_STRUCTURAL_ENTRY_PREFIXES = ('ACCEPTANCE_SIGNAL_UNVERIFIABLE', 'GROUP_DEPENDENCY_CYCLE:', 'GROUP_ID_INVALID:', 'GROUP_MAX_ITEMS:', 'GROUP_MEMBERSHIP_MISMATCH:')

_RETRYABLE_SOLVER_REPLY_PREFIXES = ('SOLVER_STRUCTURE_REPAIR_FROZEN:', 'SOLVER_STRUCTURE_REPAIR_PLAN_REQUIRED', 'SOLVER_PLAN_AND_CHANGES_AMBIGUOUS', 'SOLVER_CURRENT_PLAN_MISSING', 'SOLVER_CHANGE_NOT_OBJECT', 'SOLVER_CHANGE_FIELDS_NOT_OBJECT', 'SOLVER_CHANGE_ITEM_UNKNOWN:', 'SOLVER_CHANGE_GROUP_UNKNOWN:', 'SOLVER_CHANGE_OP_UNKNOWN:', 'SOLVER_CHANGE_PLAN_FIELD_FORBIDDEN:', 'SOLVER_SCOPE_ITEM_UNKNOWN:', 'SOLVER_ITEM_FROZEN:', 'PLAN_HAS_NO_ACCEPTANCE:', 'SOLVER_REVISION_NO_RESPONSE:', 'SOLVER_FINDING_BATCH_COVERAGE_INCOMPLETE:', 'SOLVER_FINDING_BATCH_OVERLAP:', 'SOLVER_BATCH_MISMATCH:', 'SOLVER_RESOLUTION_COVERAGE_INCOMPLETE:', 'SOLVER_GROUP_DOC_FROZEN:', 'SOLVER_GROUP_DOC_MISSING:', 'SOLVER_GROUP_DOC_INVALID:', 'SOLVER_PLAN_VERSION_CONFLICT:')

def is_retryable_solver_reply_error(error: str) -> bool:
    """True when a Solver reply error is a mechanical shape slip worth a retry."""
    text = str(error)
    if text.startswith(SOLVER_STRUCTURE_REPLY_PREFIX + ':'):
        entries = text.split(':', 1)[1].split(';')
        return bool(entries) and all((entry.strip().startswith(_GATE_STRUCTURAL_ENTRY_PREFIXES) for entry in entries))
    return any((text.startswith(prefix) for prefix in _RETRYABLE_SOLVER_REPLY_PREFIXES))
